<script setup lang="ts">
import type {Page,LibraryEntry} from '@devstore/shared-types';import {BookOpen,ArrowRight} from '@lucide/vue';
definePageMeta({middleware:'auth'});useSeoMeta({title:'我的资源 · DevStore'});
const api=useApi();const {user,error:sessionError}=useSession();const page=ref(1);
const {data,error,status,refresh}=await useAsyncData(()=> 'private:library:'+(user.value?.id||'none')+':'+page.value,()=>api.request<Page<LibraryEntry>>('/me/library?page='+page.value),{server:false});
</script>
<template><div class="container"><div class="page-head"><span class="eyebrow">YOUR KNOWLEDGE LIBRARY</span><h1>我的资源</h1><p class="muted">你的每一次投入，都在这里积累。</p></div><UserNav/><ClientOnly><p v-if="sessionError" class="error">{{ sessionError }}</p><ApiFeedback :pending="status==='pending'" :error="error" @retry="refresh"/><template v-if="data&&!error"><div v-if="data.items.length" class="product-grid"><NuxtLink v-for="item in data.items" :key="item.product_id" :to="'/tutorials/'+item.slug" class="panel"><BookOpen :size="28" style="color:var(--cyan);margin-bottom:20px"/><h2 style="font-size:19px">{{ item.title }}</h2><span class="text-link row" style="font-size:13px">继续阅读 <ArrowRight :size="15"/></span></NuxtLink></div><div v-else class="empty"><BookOpen :size="32" style="margin:0 auto 18px"/><h2 style="font-size:21px;color:var(--ink)">还没有已购教程</h2><p>探索一个感兴趣的方向，开启新的学习。</p><NuxtLink class="btn" to="/tutorials">去探索教程 <ArrowRight :size="16"/></NuxtLink></div><div v-if="data.total>20" class="pagination"><button class="btn secondary small" :disabled="page===1" @click="page--">上一页</button><span>{{ page }}</span><button class="btn secondary small" :disabled="page*20>=data.total" @click="page++">下一页</button></div></template></ClientOnly></div></template>
